// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bool reject) public {
        amount = bound(amount, 0, 1 ether);

        Adversary adv = new Adversary(reject);

        vm.deal(address(c), amount);

        bool ok;
        try c.sendMoney(address(adv), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract Adversary {
    bool public rejectPayments;
    constructor(bool _reject) payable {
        rejectPayments = _reject;
    }
    fallback() external payable {
        if (rejectPayments) revert("reject");
    }
    receive() external payable {
        if (rejectPayments) revert("reject");
    }
}
